      <div className="col-span-4" style={{ minWidth: 0 }}><Panel title="Strategy × ad type" sub="Spend and ROAS · click to filter" info="Strategies come from the campaign naming taxonomy: Protect = own-brand terms, Hijack = competitor terms, Expand = category terms.">
        <table className="tbl" style={{ tableLayout: "fixed" }}><thead><tr><th style={{ width: 70 }} />{["SP", "SB", "SD"].map((t) => <th key={t} className="r">{t}</th>)}</tr></thead>
          <tbody>{matrix.map((r) => <tr key={r.st}><td className="fw5 t-xs">{r.st}</td>{r.cells.map((c) => <td key={c.ty} style={{ padding: 3 }}>{c.has ? <div onClick={() => setCell(cell && cell[0] === r.st && cell[1] === c.ty ? null : [r.st, c.ty])} style={{ cursor: "pointer", borderRadius: 6, padding: "6px 7px", textAlign: "right", background: `rgba(29,79,196,${0.06 + 0.3 * (c.o.sp / mxSp)})`, outline: cell && cell[0] === r.st && cell[1] === c.ty ? `2px solid ${C_.blue}` : "none" }}>
            <div className="num t-xs fw6">{fmtNum(c.o.sp)}</div><div className="num t-2xs" style={{ color: safeDiv(c.o.sa, c.o.sp) < S.roasFloor ? C_.neg : C_.ink2 }}>{(safeDiv(c.o.sa, c.o.sp) || 0).toFixed(1)}×</div></div> : <div className="t-2xs c4" style={{ textAlign: "right", padding: "6px" }}>—</div>}</td>)}</tr>)}</tbody></table>
        <div className="t-2xs c4" style={{ marginTop: 6 }}>Cell shade = spend · red ROAS below the {S.roasFloor}× floor (setting).</div></Panel></div>
