      {showLow && <div className="grid issue-grid" style={{ gridTemplateColumns: "repeat(2,minmax(0,1fr))", gap: 14, paddingBottom: 12 }}>{low.map((it) => <IssueCard key={it.id} it={it} X={X} st={st[it.id]} setStatus={(v) => setStatus(it.id, v)} owner={own[it.id]} setOwner={(v) => setOwn({ ...own, [it.id]: v })} onMail={() => setMail(true)} />)}</div>}
