  "Baby & Kids": ["Johnson's", "Himalaya", "Sebamed", "Mustela"], "Health & Wellness": ["Strepsils", "Vicks", "Salonpas", "Panadol"], "Food & Beverages": ["Al Shifa", "Langnese", "Capilano", "Nature Nate's"],
