  const lines = byStore.slice(0, 10); const stores = new Set(gaps.map((g) => g.si)); const skus = new Set(gaps.map((g) => g.r.key)); const units = gaps.reduce((a, g) => a + g.qty, 0);
  const [state, setState] = useState("draft"); const [edit, setEdit] = useState(false); const [copied, setCopied] = useState(false);
