  const [intro, setIntro] = useState(`Based on the dark-store stock position as of ${snap}, the Dabur SKUs below are out of stock or under ${S.storeMin} days of cover at the listed dark stores. Central DC stock is available for every line listed, so a transfer from the DC will restore availability.`);
  const subj = `Dabur | Dark-store restock request – ${stores.size} stores, ${skus.size} SKUs – ${fmtDFull(LAST + 1)}`;
  const text = [`To: Noon Minutes Replenishment (${ksa ? "KSA" : "UAE"})`, "Cc: Dabur e-commerce team", `Subject: ${subj}`, "", "Dear Noon Minutes Replenishment Team,", "", intro, "", ...lines.map((b) => `${b.store.name} (${b.store.region}): ${b.items.map((g) => `${g.r.prod.name} × ${g.qty}`).join("; ")}`), byStore.length > lines.length ? `+ ${byStore.length - lines.length} more stores in the attached Excel` : "", "", `Total requested: ${fmtInt(units)} units across ${stores.size} dark stores. We would appreciate replenishment by ${by}. If any item is constrained at the central DC, please let us know so we can bring forward an inbound PO.`, "", "Kind regards,", `Dabur International – E-commerce, ${ksa ? "KSA" : "UAE"}`].join("\n");
